playground.css:
body { font-family: system-ui, sans-serif; padding: 18px; background: #f8fafc; color: #0f172a; }

/* Experimente mudar justify-content para center ou flex-end */
.bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  margin-bottom: 16px;
}
.actions { display: flex; gap: 8px; }
.actions button { padding: 6px 12px; border: 1px solid #cbd5e1; border-radius: 6px; background: #f1f5f9; cursor: pointer; }

/* Experimente mudar 130px para 180px ou 2 colunas fixas: repeat(2, 1fr) */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 12px;
}
.box {
  padding: 24px 12px;
  text-align: center;
  font-weight: 600;
  background: #18181b;
  color: #fafafa;
  border-radius: 8px;
}
